import{z as B,x as p,o as l,c as A,q as o,j as s,D as t,d as E,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const O=JSON.parse('{"title":"队头阻塞对照","description":"","frontmatter":{"title":"队头阻塞对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hol-blocking.md","filePath":"cs/hol-blocking.md","lastUpdated":1791413859000}'),d={name:"cs/hol-blocking.md"};function T(H,a,h,u,c,C){const r=p("Mermaid");return l(),A("div",null,[a[2]||(a[2]=o('<h1 id="队头阻塞对照" tabindex="-1">队头阻塞对照 <a class="header-anchor" href="#队头阻塞对照" aria-label="Permalink to &quot;队头阻塞对照&quot;">​</a></h1><div class="epigraph"><p>同名「队头」出现在交换结构、HTTP/1.1 串行响应、以及 TCP 字节流上的 HTTP/2；解法一层一层不同。</p><footer>—— 据 RFC 9112 / 9113；Karol HOL；RFC 9000 对照整理</footer></div><p><a href="/cs/http11-persistent-chunked">HTTP/1.1 持久</a> 把请求排成队。<a href="/cs/http2">HTTP/2 多路</a> 已给应用层解。<a href="/cs/output-queue-hol">交换机 HOL</a> 是结构。<a href="/cs/http11-persistent-chunked">上一课</a> 留下管道化失败。缺口是<strong>对照三层 HOL</strong>，避免混名。本课不把 HTTP/3 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1.1：连接上前一响应未完，后一请求的响应不能开始——应用 HOL。开多连接是笨解，伤 cc。HTTP/2：多流交错，应用 HOL 解了，但 TCP 丢一个段挡住所有流——运输 HOL。QUIC 再解运输。交换机 VOQ 解的是第三种：入端口 FIFO。PFC 暂停是第四种「整口冻」。</p><p>不要用一种队列算法「统一解决」。</p><p><span class="marginnote">教学对照。Kurose 分章讲，这里收口进阶课的词汇。</span></p><p><span class="marginnote">直觉类比：1.1 像单窗口柜台，前一人的慢业务堵住全队；H2 像叫号取件但整箱按序运输，箱子在途中碎一格、后面全部压着；交换机 HOL 则是所有卸货口共用一条进货通道，互不相干的货也互相堵。</span></p><h3 id="写-hol-必须加层" tabindex="-1">写 HOL 必须加层 <a class="header-anchor" href="#写-hol-必须加层" aria-label="Permalink to &quot;写 HOL 必须加层&quot;">​</a></h3><p>1.1 应用串行；H2 解之但仍受 TCP；H3 再解运输。交换 VOQ 是第三对象。混名无法排障。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三列对照：层、现象、对策。画三条路径。与 SCTP/QUIC 流对照。</p><p><span class="marginnote">术语翻译：HOL（Head-of-Line Blocking，队头阻塞）就是「排在最前面的没走成，后面全走不了」；VOQ（Virtual Output Queue，虚拟输出队列）是入端口为每个出端口单独开一条队，队头只堵自己要去的那一个出口。</span></p>',13)),(l(),s(i,null,{default:t(()=>[n(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20H11%5B%22HTTP%2F1.1%20%E4%B8%B2%E8%A1%8C%22%5D%20--%3E%20H2%5B%22H2%20%E5%A4%9A%E6%B5%81%22%5D%0A%20%20H2%20--%3E%20TCP%5B%22%E4%BB%8D%E5%8F%97%20TCP%20HOL%22%5D%0A%20%20TCP%20--%3E%20H3%5B%22QUIC%20%E5%A4%9A%E6%B5%81%22%5D%0A%20%20SW%5B%22%E8%BE%93%E5%85%A5%20FIFO%22%5D%20--%3E%20VOQ%5B%22VOQ%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"TSO 合并不造 1.1 HOL，只改段大小。WFQ 不修 TCP HOL。数据中心 incast 是出口队列，不是 HTTP HOL，但浏览器多连接会加重 incast。CDN 用多连接与 H2 混合。",-1)),a[5]||(a[5]=e("p",null,"命名纪律：写「HOL」必须加层。",-1)),a[6]||(a[6]=e("p",null,"H2 的运输层 HOL 是怎么发生的：",-1)),(l(),s(i,null,{default:t(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E6%B5%81%20A%20%E7%9A%84%E5%B8%A7%22%5D%20--%3E%20Q%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%20TCP%20%E8%BF%9E%E6%8E%A5%E6%8C%89%E5%BA%8F%E4%BA%A4%E4%BB%98%22%5D%0A%20%20S2%5B%22%E6%B5%81%20B%20%E7%9A%84%E5%B8%A7%22%5D%20--%3E%20Q%0A%20%20S3%5B%22%E6%B5%81%20C%20%E7%9A%84%E5%B8%A7%22%5D%20--%3E%20Q%0A%20%20Q%20--%3E%20L%7B%22%E4%B8%AD%E9%97%B4%E4%B8%A2%E4%BA%86%E4%B8%80%E4%B8%AA%E6%AE%B5%3F%22%7D%0A%20%20L%20--%20%22%E6%B2%A1%E4%B8%A2%22%20--%3E%20OK%5B%22%E5%90%84%E6%B5%81%E5%B8%A7%E6%8C%89%E6%97%B6%E5%88%B0%E8%BE%BE%22%5D%0A%20%20L%20--%20%22%E4%B8%A2%E4%BA%86%22%20--%3E%20W%5B%22%E9%87%8D%E4%BC%A0%E6%9C%9F%E9%97%B4%E5%90%8E%E7%BB%AD%E6%89%80%E6%9C%89%E5%B8%A7%E8%A2%AB%E6%89%A3%E7%95%99%22%5D%0A%20%20W%20--%3E%20R%5B%22%E9%87%8D%E4%BC%A0%E5%88%B0%E8%BE%BE%E5%90%8E%E6%8C%89%E5%BA%8F%E8%A1%A5%E4%BA%A4%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">常见误区：以为上了 HTTP/2 多路复用就不卡了。应用层确实解了串行，但底下仍是一条 TCP 字节流——一个段丢了，重传期间后面所有流的帧都得干等；这正是 QUIC 给每个流独立编号、独立交付的动机。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 HTTP/2 优先级树的全部。HTTP/3 是下一课。后课默认：H2 解应用 HOL，H3 解运输 HOL。</p><p>把所有卡顿都叫 HOL 会无法排障。</p><p>下一课<a href="/cs/http3">HTTP/3</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>1.1 应用 HOL；H2 解之、TCP 仍堵。</li><li>QUIC 解运输 HOL。</li><li>交换 HOL 是第三对象。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9112/9113/9000；Karol et al.。</li></ul>',7))])}const m=B(d,[["render",T]]);export{O as __pageData,m as default};
